const typeName=(type:string)=>type==='post'?'图文':'视频';
function candidates(e:PromotionEntry,v:PromotionVersion,key:string){return e.batches.flatMap(b=>b.attempts.filter(a=>b.creativeContext?.outputKeys[a.index-1]===key&&a.status==='completed'&&a.assetId&&!a.simulated)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)||b.attemptNumber-a.attemptNumber);}
function visibleVersion(e:PromotionEntry){return e.versions[0];}
function currentAttempts(e:PromotionEntry,v:PromotionVersion){const batch=e.batches.find(b=>b.id===v.batchIds[0]);return v.value.outputKeys.map((_,i)=>batch?.attempts.filter(a=>a.index===i+1).sort((a,b)=>b.attemptNumber-a.attemptNumber)[0]).filter((a):a is Attempt=>!!a);}
