type CreationInputProps={selected:Asset[];value:PromotionValue;product:CatalogProduct;disabled:boolean;onRequirements:(s:string)=>void;onMaterials:()=>void;onContent:()=>void;assets:Asset[];onUpload:(a:Asset)=>void;onImages:(ids:string[])=>void};
function PostCreationInput({selected,value,product,disabled,onRequirements,assets,onUpload,onImages,mode,onMode,onPatch,onBenchmark,maxTargets,inspiration}:Omit<CreationInputProps,'onContent'>&{mode:PostMode;onMode:(mode:PostMode)=>void;onPatch:(p:Partial<PromotionValue>)=>void;onBenchmark:(ids:string[])=>void;maxTargets:number;inspiration:import('react').ReactNode}){
 const [expanded,setExpanded]=useState<string>();const refs=value.benchmarkImages||[],chosen=value.selectedBenchmarkIds??refs,legacy=value.generation.inputRoles.reference||[];
 return <div className="promotion-post-input"><section className="promotion-post-mode"><Tabs value={mode} onValueChange={next=>onMode(next as PostMode)}><TabsList><TabsTrigger value="creative" disabled={disabled}>创意生成</TabsTrigger><TabsTrigger value="replicate" disabled={disabled}>爆款复刻</TabsTrigger></TabsList></Tabs></section>
 <MaterialInputRow purpose="product" label="商品图片" ids={selected.map(a=>a.id)} assets={assets} max={16} onUpload={onUpload} onChange={onImages} disabled={disabled}/>
 {!!legacy.length&&<section className="promotion-legacy-reference"><strong>旧稿通用参考图 · 待指定用途</strong><MaterialStrip ids={legacy} assets={assets} onRemove={id=>onPatch({generation:{...value.generation,inputRoles:{...value.generation.inputRoles,reference:legacy.filter(x=>x!==id)}}})}/><p className="promotion-help">保留旧稿图片，请明确用途后再报价。</p><Button variant="outline" size="sm" disabled={disabled||mode==='creative'&&legacy.length>4} onClick={()=>{const keys=legacy.map((_,i)=>value.outputKeys[i]||crypto.randomUUID());onPatch({generation:{...value.generation,count:mode==='replicate'?keys.length:value.generation.count,inputRoles:{...value.generation.inputRoles,reference:[]}},...(mode==='creative'?{inspirationImages:legacy}:{benchmarkImages:legacy,selectedBenchmarkIds:legacy,targetSettings:Object.fromEntries(legacy.map((id,i)=>[id,{outputKey:keys[i]}])),outputKeys:keys})});}}>作为{mode==='creative'?'灵感参考图':'对标原图'}</Button></section>}
 {mode==='creative'?<section><MaterialInputRow label="灵感参考图 · 可选" ids={value.inspirationImages||[]} assets={assets} max={4} onUpload={onUpload} onChange={inspirationImages=>onPatch({inspirationImages})} disabled={disabled}/>{inspiration}</section>:<><MaterialInputRow label="对标原图" ids={refs} selectedIds={chosen} onSelection={selectedBenchmarkIds=>onPatch({selectedBenchmarkIds})} assets={assets} max={maxTargets} onUpload={onUpload} onChange={onBenchmark} disabled={disabled}/><ReplicaSettings type={value.replicationType} fidelity={value.replicationFidelity} disabled={disabled} onChange={(replicationType,replicationFidelity)=>onPatch({replicationType:replicationType as PromotionValue["replicationType"],replicationFidelity:replicationFidelity as PromotionValue["replicationFidelity"]})}/><label className="promotion-replacement-label">替换对象 <span>必填，可在逐图设置中覆盖</span><Input aria-label="公共替换对象" placeholder="例如：模特身上的外套、平铺的上衣、领口细节" disabled={disabled} maxLength={500} value={value.replacementObject||''} onChange={e=>onPatch({replacementObject:e.target.value})}/></label></>}
 <section className="promotion-creative-direction"><div className="promotion-section-heading"><label htmlFor="promotion-post-requirements">商品卖点&amp;生成要求</label><CatalogAssist productId={product.id} productName={product.title} scope={`promotion-post-${mode}`} text={value.generation.requirements} onChange={onRequirements} assets={selected} disabled={disabled}/></div><Textarea id="promotion-post-requirements" aria-label="商品卖点&生成要求" rows={7} maxLength={16000} disabled={disabled} value={value.generation.requirements} placeholder={'建议包含以下信息生成更精准:\n1.产品名称\n2.核心卖点\n3.适用人群\n4.期望场景\n5.具体参数'} onChange={e=>onRequirements(e.target.value)}/></section>
 <div className="promotion-no-text"><label htmlFor="promotion-image-no-text"><strong>图片不加文字</strong><span>图片突出产品使用场景，不添加文字。</span></label><Switch id="promotion-image-no-text" checked={!!value.imageNoText} disabled={disabled} onCheckedChange={imageNoText=>onPatch({imageNoText})}/></div>
 {mode==='replicate'?<section><div className="promotion-section-heading"><h3>逐图设置</h3><span>已选 {chosen.length} / {refs.length} 张</span></div><div className="promotion-targets">{refs.map((id,i)=>{const setting=value.targetSettings?.[id],key=setting?.outputKey||value.outputKeys[i],own=setting?.productIds??selected.map(a=>a.id),a=assets.find(a=>a.id===id);const patch=(p:Partial<NonNullable<PromotionValue['targetSettings']>[string]>)=>onPatch({targetSettings:{...value.targetSettings,[id]:{...setting,outputKey:key,...p}}});return <div className={`promotion-target ${!chosen.includes(id)?'is-unselected':''}`} key={id}><div className="promotion-target-summary"><Checkbox checked={chosen.includes(id)} aria-label={`设置勾选原图${i+1}`} disabled={disabled} onCheckedChange={yes=>onPatch({selectedBenchmarkIds:yes?[...chosen,id]:chosen.filter(x=>x!==id)})}/><button aria-label={`展开原图${i+1}设置`} aria-expanded={expanded===id} onClick={()=>setExpanded(expanded===id?undefined:id)}><img src={a?.url} alt={`原图 ${i+1}`}/><span><strong>原图 {i+1} · {setting?.productIds?'独立参考':'继承公共商品图'} {own.length} 张</strong><small>{setting?.replacementObject||value.replacementObject||'请填写替换对象'}{setting?.requirements?' · 已填写局部要求':''}</small></span>{expanded===id?<ChevronUp/>:<ChevronDown/>}</button></div>{expanded===id&&<div className="promotion-target-detail"><MaterialInputRow purpose="product" label={`原图${i+1}的商品参考`} ids={own} assets={assets} max={16} disabled={disabled} onUpload={onUpload} onChange={productIds=>patch({productIds})}/>{setting?.productIds&&<Button variant="ghost" size="sm" onClick={()=>patch({productIds:undefined})}>恢复公共商品图</Button>}<label>本图替换对象<Input disabled={disabled} maxLength={500} value={setting?.replacementObject||''} placeholder={value.replacementObject||'继承整组替换对象'} onChange={e=>patch({replacementObject:e.target.value})}/></label><label>本图补充要求<Textarea disabled={disabled} maxLength={3000} rows={3} value={setting?.requirements||''} placeholder="例如：只替换领口局部，保留近景裁切" onChange={e=>patch({requirements:e.target.value})}/></label></div>}</div>;})}{!refs.length&&<p className="promotion-help">添加对标原图后，在这里逐张调整。</p>}</div></section>:null}</div>;
}
function VideoCreationInput({selected,value,product,disabled,onRequirements,onScript,onContent,assets,onUpload,onImages,onVideo,onVideoMode}:CreationInputProps&{onScript:(s:string)=>void;onVideoMode:(mode:VideoWorkflow)=>void;onVideo:(ids:string[])=>void}){
 const reverse=value.videoWorkflow==='reverse';
 const productImages=<MaterialInputRow purpose="product" label="商品图片" ids={selected.map(a=>a.id)} assets={assets} max={3} onUpload={onUpload} onChange={onImages} disabled={disabled}/>;
 const script=<section className="promotion-video-script"><div className="promotion-section-heading"><label htmlFor="promotion-video-script">{reverse?'改写后的分镜脚本':'分镜脚本 · 可选'}</label><Button variant="ghost" size="sm" onClick={onContent}>发布文案</Button></div><Textarea id="promotion-video-script" aria-label="视频分镜脚本" rows={reverse?7:4} disabled={disabled} value={value.script} maxLength={16000} placeholder={reverse?'先反推参考视频，采纳结果后检查商品、镜头与时长；也可手动编写。':'例如：开场展示穿搭，再推进领口细节，最后完整展示。'} onChange={e=>onScript(e.target.value)}/></section>;
 return <div className={'promotion-video-input '+(reverse?'is-reverse':'is-direct')}>
 <section className="promotion-post-mode promotion-video-mode"><VideoModeTabs value={reverse?'reverse':'direct'} onChange={onVideoMode} disabled={disabled}/></section>
 {reverse?<><section className="promotion-video-reference"><div className="promotion-section-heading"><h3>同行参考视频</h3><span>只用于主动反推</span></div><div className="promotion-video-source"><MaterialPicker label={value.referenceVideoId?'更换参考视频':'上传或选择参考视频'} video assets={assets} selected={value.referenceVideoId?[value.referenceVideoId]:[]} max={1} onUpload={onUpload} onChange={onVideo} disabled={disabled}/>{value.referenceVideoId?<MaterialStrip ids={[value.referenceVideoId]} assets={assets} onRemove={()=>onVideo([])}/>:<p>选择想借鉴的镜头、节奏与表达方式。</p>}</div>{value.referenceVideoId&&<CatalogAssist productId={product.id} productName={product.title} action="reverse-video" text={value.script} assets={assets.filter(a=>a.id===value.referenceVideoId)} triggerLabel="反推镜头与提示词" onChange={onScript}/>}<p className="promotion-help">MP4 / WebM · ≤30MB · ≤120 秒</p></section>{productImages}</>:productImages}
 <section className="promotion-creative-direction"><div className="promotion-section-heading"><label htmlFor="promotion-video-requirements">{reverse?'本商品的调整要求':'视频创作要求'}</label><CatalogAssist productId={product.id} productName={product.title} scope="promotion-video" text={value.generation.requirements} onChange={onRequirements} assets={selected} disabled={disabled}/></div><Textarea id="promotion-video-requirements" aria-label="视频创作要求" rows={4} disabled={disabled} maxLength={16000} value={value.generation.requirements} placeholder={reverse?'说明需要替换的商品、场景与文案，以及希望保留的镜头表达…':'描述商品展示方式、人物动作、场景与镜头节奏…'} onChange={e=>onRequirements(e.target.value)}/><div className="promotion-creative-tags">{['穿搭展示','领口细节','面料特写','缓慢推进'].map(text=><Button key={text} variant="outline" size="sm" disabled={disabled} onClick={()=>onRequirements([value.generation.requirements,text].filter(Boolean).join('，'))}><Plus/>{text}</Button>)}</div></section>
 {reverse?script:<details className="promotion-optional-script"><summary>分镜脚本与发布文案{value.script?' · 已填写':' · 可选'}</summary>{script}</details>}
 </div>;
}
function PromotionPreview({entry:e,assets,onRefresh,onReplicate}:{entry:PromotionEntry&{derivatives?:PromotionWork[]};assets:Asset[];onRefresh:()=>Promise<unknown>;onReplicate:(regenerate:boolean)=>void}){
 const confirmKey=useRef(crypto.randomUUID());const [confirmUnknown,setConfirmUnknown]=useState(false);
 const v=visibleVersion(e),[title,setTitle]=useState(v.value.title),[body,setBody]=useState(v.value.body),[order,setOrder]=useState(v.value.outputKeys),[selection,setSelection]=useState<Record<string,string>>(v.selection),[view,setView]=useState<Asset>(),[busy,setBusy]=useState(false),[details,setDetails]=useState(false),[performance,setPerformance]=useState(false),[retry,setRetry]=useState<{attempt:Attempt;quote:import('../../../packages/contracts').GenerationQuote}>();
 useEffect(()=>{setTitle(v.value.title);setBody(v.value.body);setOrder(v.value.outputKeys);setSelection(v.selection);confirmKey.current=crypto.randomUUID();setConfirmUnknown(false);},[v.id]);
 async function confirm(){setBusy(true);try{const next=await api<PromotionVersion>(`/promotions/${e.work.id}/confirm`,{revision:e.work.revision,versionId:v.id,title,body,order,selection:Object.fromEntries(order.map(key=>[key,candidates(e,v,key)[0]?.id||v.selection[key]||''])),idempotencyKey:confirmKey.current});await onRefresh();toast.success('作品已保存');}catch(err){if(!(err as {status?:number}).status||(err as {status:number}).status>=500)setConfirmUnknown(true);toast.error((err as Error).message);}finally{setBusy(false);}}
 const draggedPage=useRef<number|null>(null);
 const complete=order.every(key=>!!v.media[key]||!!candidates(e,v,key).length);
 function move(i:number,delta:number){const next=[...order];[next[i],next[i+delta]]=[next[i+delta],next[i]];setOrder(next);}
 return <div className="promotion-sheet-body"><SavePromptButton source={{kind:"promotion",id:e.work.id,versionId:v.id}} disabled={!Object.keys(v.media).length&&!e.batches.some(b=>b.attempts.some(a=>a.status==='completed'&&!a.simulated))}/>{v.legacy&&<p className="muted">历史文案未保存，当前商品旧稿在创作栏中保留，尚未确认。</p>}
 <div className="promotion-preview-pages">{order.map((key,i)=>{const options=candidates(e,v,key),chosen=options[0],asset=assets.find(a=>a.id===(chosen?.assetId||v.media[key]));const attempts=e.batches.filter(b=>v.batchIds.includes(b.id)).flatMap(b=>b.attempts.filter(a=>b.creativeContext?.outputKeys[a.index-1]===key)),latest=attempts.sort((a,b)=>b.attemptNumber-a.attemptNumber)[0];return <section key={key} draggable={e.work.type==='post'} onDragStart={event=>{draggedPage.current=i;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',key);}} onDragOver={event=>event.preventDefault()} onDrop={event=>{event.preventDefault();const from=draggedPage.current;if(from!==null&&from!==i){const next=[...order];const [item]=next.splice(from,1);next.splice(i,0,item);setOrder(next);}draggedPage.current=null;}} onDragEnd={()=>{draggedPage.current=null;}}><div className="promotion-page-toolbar"><strong>{e.work.type==='post'?`第 ${i+1} 页`:'成片'}</strong>{e.work.type==='post'&&<><IconButton icon={ArrowUp} label={`上移第${i+1}页`} disabled={i===0} onClick={()=>move(i,-1)}/><IconButton icon={ArrowDown} label={`下移第${i+1}页`} disabled={i===order.length-1} onClick={()=>move(i,1)}/></>}</div>{asset?.type==='video'?<VideoPlayer src={asset.url}/>:asset?<button className="promotion-preview-image" onClick={()=>setView(asset)} aria-label={`放大第${i+1}页`}><img src={asset.url} alt={`作品第${i+1}页`}/></button>:<div className="promotion-missing-page"><Images/><p>{latest?.error||latest?.step||'本页尚无可用结果'}</p></div>} {latest?.status==='failed'&&<Button variant="outline" onClick={async()=>{try{const quote=await api<import('../../../packages/contracts').GenerationQuote>(`/attempts/${latest.id}/retry-quote`,{revision:latest.revision});setRetry({attempt:latest,quote});}catch(err){toast.error((err as Error).message);}}}>仅补做本页 · 先查报价</Button>}</section>;})}</div>
 {confirmUnknown&&<p role="status">作品保存结果待核实，请关闭后重新打开查看，避免重复修订。</p>}<label>推广标题<Input aria-label="作品推广标题" value={title} maxLength={500} onChange={e=>setTitle(e.target.value)}/></label><label>推广正文<Textarea aria-label="作品推广正文" value={body} maxLength={16000} rows={5} onChange={e=>setBody(e.target.value)}/></label><div className="promotion-preview-actions"><Button disabled={busy||!complete||confirmUnknown} onClick={()=>void confirm()}>{busy?<LoaderCircle className="spin"/>:null}保存文案与排序</Button><Button variant="outline" onClick={()=>void download(e.work.id,v.id)}><Download/>{complete?'下载作品':'下载已有素材'}</Button></div>{!complete&&<p className="muted">缺页时可下载已有素材；补齐后即可保存完整作品。</p>}
 {v.confirmed&&<><label className="promotion-worthy"><Checkbox checked={e.worthyVersionIds.includes(v.id)} onCheckedChange={worthy=>void api(`/promotions/${e.work.id}/worthy`,{versionId:v.id,worthy:!!worthy},'PUT').then(onRefresh).catch(err=>toast.error(err.message))}/><Star/>值得复刻</label><div className="flex gap-2"><Button variant="outline" onClick={()=>onReplicate(false)}>复刻新作品</Button><Button variant="ghost" onClick={()=>onReplicate(true)}>重新生成</Button><Button variant="ghost" onClick={()=>setPerformance(true)}>记录表现</Button></div></>}
 {e.records.filter(r=>r.versionId===v.id).map(r=><div className="promotion-performance" key={r.id}><strong>人工录入 · {dateTime(r.recordedAt)}</strong><p>发布 {r.publishedAt||'未填写'}{r.url?' · 已附发布链接':''}</p><dl>{(['plays','likes','comments','favorites','shares','orders','revenue'] as const).map((key,i)=><div key={key}><dt>{['播放／曝光','点赞','评论','收藏','分享','成交订单','成交金额'][i]}</dt><dd>{r[key]===null?'未填写':r[key]}</dd></div>)}</dl>{r.url&&<a href={r.url} target="_blank" rel="noreferrer">查看发布链接</a>}<p>{r.notes}</p></div>)}
 <Button variant="ghost" onClick={()=>setDetails(!details)}>{details?<ChevronUp/>:<ChevronDown/>}任务、费用与来源详情</Button>{details&&<div className="promotion-details">{e.work.sourceWorkId&&<Button variant="link" onClick={()=>void copy(e.work.sourceWorkId!)}>复刻自 {e.work.sourceWorkId}</Button>}{e.derivatives?.map(w=><p key={w.id}>直接衍生：{w.name}</p>)}<h3>脚本与创作快照</h3><pre>{v.value.script||v.value.generation.requirements}</pre><Button variant="outline" onClick={()=>void copy(v.value.script||v.value.generation.requirements)}>复制提示词</Button><h3>输入素材与参数</h3><MaterialStrip ids={Object.values(v.value.generation.inputRoles).flat()} assets={assets}/><p>{v.value.generation.modelId} · {v.value.generation.aspectRatio} · {Object.entries(v.value.generation.parameters).map(([key,value])=>`${parameterLabel(key)}：${parameterValueLabel(key,value)}`).join(' · ')}</p>{e.batches.filter(b=>v.batchIds.includes(b.id)).flatMap(b=>b.attempts).map(a=><div className="promotion-attempt" key={a.id}><Status status={a.status}/><p>第 {a.index} 页 · {a.step}</p><p>供应商任务号：{a.upstreamTaskId||'尚未取得'}</p><p>费用：{a.billing?.cost??'待结算'} {a.billing?.unit||'算力'} · 退款：{a.billing?.refunded?(a.billing.refundedAmount??'待确认'):a.model.provider==='token01'?'平台核对':'无'} {a.billing?.note}</p>{a.error&&<p role="alert">{a.error}</p>}<pre>{a.prompt}</pre></div>)}</div>}
 <MediaModal asset={view} onClose={()=>setView(undefined)}/>
 <Modal open={!!retry} onClose={()=>setRetry(undefined)} title="确认补做本页" description="只创建这一页的新尝试，保留其他成功页。">{retry&&<><p>最多 {retry.quote.maximum} {retry.quote.unit}，当前可用 {retry.quote.available??'由平台校验'} {retry.quote.available===null?'':retry.quote.unit}</p>{retry.quote.note&&<p>{retry.quote.note}</p>}<Button disabled={busy||!retry.quote.affordable} onClick={async()=>{setBusy(true);try{await api(`/attempts/${retry.attempt.id}/retry`,{revision:retry.attempt.revision,maximumCost:retry.quote.maximum});setRetry(undefined);await onRefresh();}catch(err){toast.error((err as Error).message);}finally{setBusy(false);}}}>确认补做</Button></>}</Modal>
 {performance&&<PerformanceDialog versionId={v.id} workId={e.work.id} records={e.records} onClose={()=>setPerformance(false)} onSaved={async()=>{setPerformance(false);await onRefresh();}}/>}
 </div>;
}
function ReplicationDialog({entry:e,regenerate,productId,onClose,onDone}:{entry:PromotionEntry;regenerate:boolean;productId:string;onClose:()=>void;onDone:(id:string,type:'post'|'video',mode?:PostMode,workflow?:VideoWorkflow)=>void}){
 const versionId=visibleVersion(e).id;const [target,setTarget]=useState(regenerate?e.work.productId:productId),[replace,setReplace]=useState(false),[busy,setBusy]=useState(false),[search,setSearch]=useState(''),[page,setPage]=useState(1);
 const sourceMode=postModeOf(e.versions.find(v=>v.id===versionId)?.value||{}),sourceWorkflow=e.versions.find(v=>v.id===versionId)?.value.videoWorkflow||'direct',modeQuery=e.work.type==='post'?'?mode='+sourceMode:'?videoWorkflow='+sourceWorkflow;
 const products=useQuery({queryKey:['replication-products',search,page],queryFn:()=>api<CatalogList>(`/catalog/products?search=${encodeURIComponent(search)}&page=${page}`)}),draft=useQuery({queryKey:['replication-draft',target,e.work.type,sourceMode,sourceWorkflow],queryFn:()=>api<PromotionDraft>(`/catalog/products/${target}/promotion-drafts/${e.work.type}${modeQuery}`)});
 const draftStorage=`promotion-draft:${draft.data?.id||`${target}:${e.work.type}${e.work.type==='post'?':'+sourceMode:''}`}`,cachedDraft=localStorage.getItem(draftStorage);
 const hasDraft=!!cachedDraft||draft.data&&!!(draft.data.value.title||draft.data.value.body||draft.data.value.generation.requirements||draft.data.value.script||Object.keys(draft.data.value.pageRequirements).length||draft.data.value.referenceVideoId||draft.data.value.referenceCopy||draft.data.value.benchmarkImages?.length||draft.data.value.inspirationImages?.length||draft.data.value.generation.inputRoles.reference?.length);
 return <Modal open onClose={onClose} title={regenerate?'为当前作品重新生成':'复刻为新作品'} description="先载入草稿并编辑，查询报价并确认后才生成。"><div className="promotion-dialog-fields">{!regenerate&&<><Input aria-label="搜索目标商品" placeholder="搜索目标商品" value={search} onChange={event=>{setSearch(event.target.value);setPage(1);}}/><label>目标商品<FormSelect aria-label="复刻目标商品" value={target} options={[{value:productId,label:'当前商品'},...(productId!==e.work.productId?[{value:e.work.productId,label:'来源商品'}]:[]),...(products.data?.items.filter(p=>![productId,e.work.productId].includes(p.id)).map(p=>({value:p.id,label:p.title}))||[])]} onValueChange={id=>{setTarget(id);setReplace(false);}}/></label>{!!products.data&&products.data.total>20&&<div className="flex gap-2"><Button size="sm" variant="outline" disabled={page===1} onClick={()=>setPage(p=>p-1)}>上一页</Button><span>第{page}页</span><Button size="sm" variant="outline" disabled={page*20>=products.data.total} onClick={()=>setPage(p=>p+1)}>下一页</Button></div>}</>}
 <p className="muted">{target===e.work.productId?'继承内容编排、脚本、商品图和合法参数。':'将替换为目标商品资料与商品图；来源商品事实会清除，逐页内容与脚本需重新核对。'}</p>{hasDraft&&<label className="flex gap-2"><Checkbox checked={replace} onCheckedChange={x=>setReplace(!!x)}/>备份目标商品原草稿，并替换为本次{regenerate?'重新生成':'复刻'}草稿</label>}{draft.error&&<p role="alert">{draft.error.message}</p>}<div className="modal-actions"><Button variant="outline" onClick={onClose}>取消</Button><Button disabled={busy||!draft.data||!!hasDraft&&!replace||!versionId} onClick={async()=>{setBusy(true);try{if(sourceWorkflow==='shot-remake'){const v=e.versions.find(v=>v.id===versionId)!;await api('/video-remakes/'+v.value.remakeJobId+'/replicate',{compositionId:v.value.remakeCompositionId,targetId:target,idempotencyKey:crypto.randomUUID()});onDone(target,'video',undefined,'shot-remake');return;}await api(`/promotions/${e.work.id}/replicate`,{versionId,targetId:target,revision:draft.data!.revision,replace,regenerate});if(cachedDraft)localStorage.setItem(`promotion-draft-backup:${target}:${Date.now()}`,cachedDraft);localStorage.removeItem(draftStorage);onDone(target,e.work.type,e.work.type==='post'?sourceMode:undefined,e.work.type==='video'?sourceWorkflow:undefined);toast.success('已载入独立草稿，请检查后查询报价');}catch(err){toast.error((err as Error).message);}finally{setBusy(false);}}}>{busy?<LoaderCircle className="spin"/>:<Copy/>}载入创作草稿</Button></div></div></Modal>;
}
function PerformanceDialog({versionId,workId,records,onClose,onSaved}:{versionId:string;workId:string;records:PromotionPerformanceRecord[];onClose:()=>void;onSaved:()=>Promise<void>}){
 const publication=useRef(crypto.randomUUID());const initial={versionId,publicationId:publication.current,url:'',publishedAt:'',recordedAt:new Date().toISOString(),plays:null,likes:null,comments:null,favorites:null,shares:null,orders:null,revenue:null,notes:''};const [value,setValue]=useState<Omit<PromotionPerformanceRecord,'id'|'manual'>>(initial),[busy,setBusy]=useState(false);const pubs=[...new Map(records.filter(r=>r.versionId===versionId).map(r=>[r.publicationId,r])).values()];
 return <Modal open onClose={onClose} title="记录作品表现" description="人工录入，记录当前作品表现；空白表示未填写，0 表示实际为零。"><div className="promotion-dialog-fields"><FormSelect aria-label="发布记录" value={value.publicationId} options={[{value:initial.publicationId,label:'新建一次发布'},...pubs.map(r=>({value:r.publicationId,label:r.url||r.publishedAt||'未填写发布链接的记录'}))]} onValueChange={id=>{const r=pubs.find(r=>r.publicationId===id);setValue({...initial,publicationId:id,url:r?.url||'',publishedAt:r?.publishedAt||''});}}/><label>发布链接<Input aria-label="发布链接" value={value.url} onChange={e=>setValue({...value,url:e.target.value})}/></label><label>发布时间（可选）<Input aria-label="发布时间" placeholder="例如：2026-10-29 14:30" value={value.publishedAt} onChange={e=>setValue({...value,publishedAt:e.target.value})}/></label><p className="muted">数据记录时间：{dateTime(value.recordedAt)}</p><div className="promotion-metrics-grid">{(['plays','likes','comments','favorites','shares','orders','revenue'] as const).map((key,i)=><label key={key}>{['播放／曝光','点赞','评论','收藏','分享','成交订单','成交金额'][i]}<NumberInput aria-label={['播放／曝光','点赞','评论','收藏','分享','成交订单','成交金额'][i]} allowEmpty placeholder="未填写" min={0} step={key==='revenue'?0.01:1} value={value[key]??''} onValueChange={n=>setValue({...value,[key]:n===''?null:Number(n)})}/></label>)}</div><label>备注<Textarea value={value.notes} maxLength={4000} onChange={e=>setValue({...value,notes:e.target.value})}/></label><div className="modal-actions"><Button variant="outline" onClick={onClose}>取消</Button><Button disabled={busy} onClick={async()=>{setBusy(true);try{await api(`/promotions/${workId}/performance`,value);await onSaved();}catch(err){toast.error((err as Error).message);}finally{setBusy(false);}}}>保存本次记录</Button></div></div></Modal>;
}
